function FUB_T(k)
 local lang=(EUB_DB and EUB_DB.language) or 'auto'
 if lang=='auto' then lang=GetLocale() or 'enUS' end
 if lang=='esMX' then lang='esES' end
 return (FUB_TRANSLATIONS[lang] and FUB_TRANSLATIONS[lang][k]) or en[k] or k
end
